```typescript
// in generateImage.ts
import { Modality } from "@google/genai"; // Added Modality import for future use

async function generateImage(restorationFile: File, prompt: string, apiKey: string) {
    let attempts = 0;
    const maxAttempts = 3;
    let blockReason: string | undefined = undefined;

    while (attempts < maxAttempts) {
        try {
            console.log(`Attempt ${attempts + 1} to generate image`);
            // Initialize with default values.
            const response = await googleGenAI.generateContent({
                contents: [{
                    parts: [
                        { text: prompt },
                        {
                            fileData: {
                                mimeType: restorationFile.type,
                                data: await restorationFile.arrayBuffer()
                            },
                            inlineData: {
                                mimeType: restorationFile.type,
                                data: await restorationFile.arrayBuffer()
                            }
                        }
                    ],
                }],
                generationConfig: {
                    temperature: 0.1,
                    topP: 1.0,
                    topK: 32,
                    maxOutputTokens: 2048,
                },
            });
            console.log("Response received:", response);
            if (response.promptFeedback?.blockReason) {
                blockReason = response.promptFeedback.blockReason;
                throw new Error(`Safety block: ${blockReason}`);
            }

            const candidates = response.candidates;
            if (!candidates || candidates.length === 0) {
                console.warn("No candidates found in the API response.");
                throw new Error("No image candidates returned from the API.");
            }

            const content = candidates[0].content;
            if (!content) {
                console.warn("No content found in the first candidate.");
                throw new Error("No content in candidate.");
            }
            if (!content.parts || content.parts.length === 0) {
                console.warn("No parts found in the content of the first candidate.");
                throw new Error("No parts found in candidate content.");
            }

            const image: string = (content.parts[0] as any).fileData?.data;

            if (!image) {
                console.warn("Image data is missing from the API response.");
                throw new Error("Missing image data in API response.");
            }
            return [image];

        } catch (error: any) {
            attempts++;
            console.error(`Attempt ${attempts} failed:`, error);
            if (error?.message?.includes("Safety block") || error?.message?.includes("blockReason")) {
                console.warn("Safety block detected, stopping retries.");
                break; // Stop retrying if safety block
            }
            if (error && error.isFatal === true) {
                console.error("Fatal error detected, stopping retries.");
                throw error;
            }
            if (attempts < maxAttempts) {
                console.log(`Retrying in ${attempts * 1000}ms...`);
                await new Promise(resolve => setTimeout(resolve, attempts * 1000));
            } else {
                console.error("Max retries reached. Returning null.");
                throw error;
            }
        }
    }
    if (blockReason) {
        throw new Error(`Safety blocked. Reason: ${blockReason}`);
    }
    throw new Error(`Failed to generate image after ${maxAttempts} attempts.`);
}
```

